/**
 * Bindings for the Worker. `Env` is generated by `wrangler types` from wrangler.jsonc
 * (vars, D1, R2, Queue). Vars are widened to `string` because environments override them,
 * and secrets are added here because they are set with `wrangler secret put`.
 */
export type Secrets = {
  SESSION_SECRET?: string;
  ENCRYPTION_KEY?: string;
  ANTHROPIC_API_KEY?: string;
  JIRA_OAUTH_CLIENT_ID?: string;
  JIRA_OAUTH_CLIENT_SECRET?: string;
  MCP_BOOTSTRAP_TOKEN?: string;
  /** Shared secret for the Ubuntu-cron-triggered /internal/cron/:job endpoint (replaces the Workers Cron Trigger). */
  CRON_SECRET?: string;
  /** Shared HMAC secret for the suite-wide super-admin SSO handshake (GET /api/auth/sso). Set with `wrangler secret put`. */
  SAAS_SSO_SECRET?: string;
};

type VarKeys = "APP_NAME" | "APP_VERSION" | "WEB_ORIGIN" | "WEB_ORIGINS_EXTRA" | "JOB_MODE" | "AI_PROVIDER" | "AI_MODEL" | "JIRA_MODE" | "JIRA_OAUTH_REDIRECT_PATH" | "MAX_UPLOAD_BYTES" | "SESSION_TTL_HOURS" | "RETENTION_RAW_IMPORT_DAYS" | "RETENTION_REPORT_DAYS" | "RETENTION_AUDIT_DAYS";

export type Bindings = Omit<Env, VarKeys> & Record<VarKeys, string> & Secrets;

export type QueueJob =
  | { type: "ANALYSE_IMPORT"; import_id: string; correlation_id: string }
  | { type: "SYNC_JOB"; sync_job_id: string; correlation_id: string }
  | { type: "GENERATE_REPORT"; report_job_id: string; correlation_id: string };
